package dev.openai.echograve;
import java.time.*; import java.util.*;
public class EchoGraveTest { public static void main(String[] args){ deathCreatesGraveAndCompassText(); graveDecaysAndPermissionsWork(); backCooldownWorks(); placementOffsetsStartAtDeathBlock(); }
 static void deathCreatesGraveAndCompassText(){ EchoGrave mod=new EchoGrave(EchoGraveConfig.defaults()); mod.recordDeath("p1","Steve","fell",new Position("overworld",10,64,0),7,List.of("minecraft:stone")); if(!mod.compassText("p1", new Position("overworld",0,64,0)).contains("east")) throw new AssertionError("compass should point east"); }
 static void graveDecaysAndPermissionsWork(){ GraveRecord g=new GraveRecord(UUID.randomUUID(),"owner","Alex","lava",new Position("overworld",0,0,0),Instant.EPOCH,0,List.of(),Set.of("owner"),5); if(g.canOpen("stranger",Instant.EPOCH.plusSeconds(1))) throw new AssertionError("stranger opened fresh grave"); if(!g.canOpen("stranger",Instant.EPOCH.plusSeconds(5))) throw new AssertionError("decayed grave should be public"); }
 static void backCooldownWorks(){ BackTeleportState state=new BackTeleportState(); state.markBackUsed("p", Instant.EPOCH); if(state.canUseBack("p", Instant.EPOCH.plusSeconds(10), java.time.Duration.ofSeconds(60), false)) throw new AssertionError("cooldown failed"); if(!state.canUseBack("p", Instant.EPOCH.plusSeconds(10), java.time.Duration.ofSeconds(60), true)) throw new AssertionError("bypass failed"); }
 static void placementOffsetsStartAtDeathBlock(){ GravePlacement.BlockOffset first=GravePlacement.candidateOffsets().get(0); if(first.x()!=0||first.y()!=0||first.z()!=0) throw new AssertionError("first grave placement candidate must be the death block"); }}
